// Holographic Foil — ported from Joey's Refract legacy_engines.v6.js
// Thin-film iridescent shimmer driven by fbm + view sweep. Used on car body
// and select world objects. Uniforms match the Refract contract so they can
// be driven by uHeat (boost intensity) and uFlow (speed).
export const holographicFoilVertex = /* glsl */ `
varying vec2 vUv;
varying vec3 vNormal;
varying vec3 vViewDir;
void main() {
  vUv = uv;
  vNormal = normalize(normalMatrix * normal);
  vec4 worldPos = modelMatrix * vec4(position, 1.0);
  vViewDir = normalize(cameraPosition - worldPos.xyz);
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}
`;

// Fragment adapted from Refract "Holographic Foil" — clip-space vert replaced,
// fresnel rim added for edge brightening on 3D geometry.
export const holographicFoilFragment = /* glsl */ `
precision highp float;
varying vec2 vUv;
varying vec3 vNormal;
varying vec3 vViewDir;
uniform float uTime;
uniform float uHeat;
uniform float uFlow;

vec3 h3(vec3 p){
  p=vec3(dot(p,vec3(127.1,311.7,74.7)),dot(p,vec3(269.5,183.3,246.1)),dot(p,vec3(113.5,271.9,124.6)));
  return -1.0+2.0*fract(sin(p)*43758.5453);
}
float gn(vec3 p){
  vec3 i=floor(p),f=fract(p);
  vec3 u=f*f*(3.0-2.0*f);
  return mix(
    mix(mix(dot(h3(i+vec3(0,0,0)),f-vec3(0,0,0)),dot(h3(i+vec3(1,0,0)),f-vec3(1,0,0)),u.x),
        mix(dot(h3(i+vec3(0,1,0)),f-vec3(0,1,0)),dot(h3(i+vec3(1,1,0)),f-vec3(1,1,0)),u.x),u.y),
    mix(mix(dot(h3(i+vec3(0,0,1)),f-vec3(0,0,1)),dot(h3(i+vec3(1,0,1)),f-vec3(1,0,1)),u.x),
        mix(dot(h3(i+vec3(0,1,1)),f-vec3(0,1,1)),dot(h3(i+vec3(1,1,1)),f-vec3(1,1,1)),u.x),u.y),u.z);
}
float fbm(vec3 p){
  float a=0.5,s=0.0;
  for(int i=0;i<6;i++){s+=a*gn(p);p=p*2.03+vec3(7.0);a*=0.5;}
  return s;
}

void main() {
  vec2 uv = vUv * 2.0 - 1.0;
  float r = length(uv);

  // iridescent foil: fbm-driven cos-palette
  float a = fbm(vec3(vUv * 3.0, uTime * 0.1));
  vec3 foil = 0.5 + 0.5 * cos(6.2831 * (a * 2.0 + r * 1.5 + vec3(0.0, 0.33, 0.67) + uTime * 0.2 + uv.x * 1.5));

  float shimmer = pow(0.5 + 0.5 * sin((uv.x + uv.y) * 8.0 + uTime * 2.0), 2.0);
  vec3 col = foil * (0.5 + 0.5 * shimmer) * (0.8 + uHeat * 0.6);

  // Fresnel rim brightening on 3D geometry
  float fresnel = pow(1.0 - max(0.0, dot(vNormal, vViewDir)), 2.8);
  col += foil * fresnel * 0.7;

  // Tint toward the midnight palette (blue-dominant, keep dark)
  col = mix(col * 0.15, col, 0.5 + 0.5 * sin(uTime * 0.3));
  col = clamp(col, 0.0, 1.0);

  float alpha = max(col.r, max(col.g, col.b));
  gl_FragColor = vec4(col, alpha * (0.6 + uHeat * 0.4));
}
`;

// Halftone Sun — dot-matrix disc shader for distant horizon "suns".
// Derived from Joey's Refract "Halftone" engine but adapted for 3D disc
// geometry: concentric rings of dots with color cycling by angle and radius.
// Two color modes: MODE_BLUE (electric blue dominant) and MODE_PINK (magenta).

export const halftoneSunVertex = /* glsl */ `
varying vec2 vUv;
void main() {
  vUv = uv;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}
`;

export const halftoneSunFragment = /* glsl */ `
precision highp float;
varying vec2 vUv;
uniform float uTime;
uniform float uHeat;
uniform float uMode; // 0 = blue, 1 = pink/magenta

vec3 h3(vec3 p){
  p=vec3(dot(p,vec3(127.1,311.7,74.7)),dot(p,vec3(269.5,183.3,246.1)),dot(p,vec3(113.5,271.9,124.6)));
  return -1.0+2.0*fract(sin(p)*43758.5453);
}
float gn(vec3 p){
  vec3 i=floor(p),f=fract(p);vec3 u=f*f*(3.0-2.0*f);
  return mix(
    mix(mix(dot(h3(i+vec3(0,0,0)),f-vec3(0,0,0)),dot(h3(i+vec3(1,0,0)),f-vec3(1,0,0)),u.x),
        mix(dot(h3(i+vec3(0,1,0)),f-vec3(0,1,0)),dot(h3(i+vec3(1,1,0)),f-vec3(1,1,0)),u.x),u.y),
    mix(mix(dot(h3(i+vec3(0,0,1)),f-vec3(0,0,1)),dot(h3(i+vec3(1,0,1)),f-vec3(1,0,1)),u.x),
        mix(dot(h3(i+vec3(0,1,1)),f-vec3(0,1,1)),dot(h3(i+vec3(1,1,1)),f-vec3(1,1,1)),u.x),u.y),u.z);
}
float fbm(vec3 p){float a=0.5,s=0.0;for(int i=0;i<5;i++){s+=a*gn(p);p=p*2.03+vec3(7.0);a*=0.5;}return s;}

void main() {
  vec2 uv = vUv * 2.0 - 1.0;
  float r = length(uv);
  float ang = atan(uv.y, uv.x);

  // Subtle fbm warp for organic feel
  float field = fbm(vec3(uv * 1.2, uTime * 0.08)) * 0.5 + 0.5;
  field *= smoothstep(1.1, 0.1, r);

  // Concentric ring structure (5 rings tighten toward center)
  float rings = sin(r * 18.0 - uTime * 0.35) * 0.5 + 0.5;
  rings = mix(rings, field, 0.4);

  // Halftone dot grid — denser toward center
  float dotScale = mix(24.0, 12.0, r);
  vec2 g = fract(uv * dotScale) - 0.5;
  float dt = smoothstep(rings * 0.52, rings * 0.52 - 0.1, length(g));

  // Color selection: blue or pink dominant, cycling with angle and time
  vec3 cBlue = vec3(0.0, 0.64, 1.0);
  vec3 cPink = vec3(1.0, 0.12, 0.43);
  vec3 cCyan = vec3(0.0, 0.88, 0.88);

  vec3 col;
  float hue = ang / 6.2831 + 0.5 + uTime * 0.04;
  if (uMode < 0.5) {
    // Blue mode: blue → cyan gradient with magenta accents
    col = mix(cBlue, cCyan, 0.5 + 0.5 * sin(hue * 4.0 + r * 3.0));
    col = mix(col, cPink, 0.12 * (0.5 + 0.5 * sin(hue * 7.0)));
  } else {
    // Pink mode: magenta → blue gradient
    col = mix(cPink, cBlue, 0.5 + 0.5 * sin(hue * 4.0 + r * 3.0));
    col = mix(col, cCyan, 0.08 * (0.5 + 0.5 * sin(hue * 9.0)));
  }

  // Radial fade + dot mask
  float fade = smoothstep(1.05, 0.05, r);
  col = col * dt * (0.9 + uHeat * 0.3) * fade;

  float alpha = (col.r + col.g + col.b) > 0.0 ? fade * 0.85 : 0.0;
  gl_FragColor = vec4(col, alpha);
}
`;

// Shared track geometry data — source of truth for curve, gates and boost pads.
// Importing this module is side-effect-free (no Three.js side effects on module
// load beyond the CatmullRomCurve3 constructor).
import * as THREE from 'three';

export const TRACK_WIDTH = 26;

// Exact 9-point closed circuit from the vanilla arena — never change these
// control points without updating the physics trimesh collider too.
export const curve = new THREE.CatmullRomCurve3(
  [
    new THREE.Vector3(0, 3, 0),
    new THREE.Vector3(150, 3, 0),
    new THREE.Vector3(260, 12, 60),
    new THREE.Vector3(300, 30, 180),
    new THREE.Vector3(220, 42, 300),
    new THREE.Vector3(80, 34, 360),
    new THREE.Vector3(-60, 22, 300),
    new THREE.Vector3(-120, 10, 160),
    new THREE.Vector3(-60, 4, 40),
  ],
  true,
  'catmullrom',
  0.35
);

// t-values for gates (4 checkpoints, last = finish line)
export const GATE_T_VALUES = [0.22, 0.46, 0.72, 0.985];

// t-values for boost pads
export const BOOST_PAD_T_VALUES = [0.06, 0.3, 0.55, 0.8];

// Gate trigger radius
export const GATE_RADIUS = TRACK_WIDTH / 2 + 6;

// Precomputed gate world data (position, radius, isFinish)
export const GATES = GATE_T_VALUES.map((t, index) => ({
  position: curve.getPointAt(t).clone(),
  radius: GATE_RADIUS,
  index,
  isFinish: index === GATE_T_VALUES.length - 1,
}));

// Spawn point at t=0.005 (just ahead of start line)
export function getSpawn() {
  const t = 0.005;
  const point = curve.getPointAt(t);
  const tangent = curve.getTangentAt(t);
  return {
    position: point.clone().add(new THREE.Vector3(0, 2.2, 0)),
    heading: Math.atan2(tangent.x, tangent.z),
  };
}

// Module-level mutable car physics state — read by ChaseCamera and HUD each
// frame without triggering React re-renders. Car.jsx writes; others read.
import * as THREE from 'three';

export const carPhysics = {
  position: new THREE.Vector3(0, 3, 0),
  heading: 0,
  velocity: new THREE.Vector3(),
  boost: 100,
  isBoosting: false,
};

// Zustand store for race state — countdown, gates, timer, finish.
// Per-frame numeric values (speed, boost level) live in carState.js to avoid
// constant re-renders. Only infrequent state changes live here.
import { create } from 'zustand';
import { GATES } from './trackData.js';

export const useRaceStore = create((set, get) => ({
  // 'countdown' | 'racing' | 'finished'
  phase: 'countdown',
  countdown: 3.0,
  raceTime: 0,
  nextGate: 0,
  gateCount: GATES.length,

  // Called each frame from Car.jsx physics loop
  tickCountdown: (dt) => {
    const { phase, countdown } = get();
    if (phase !== 'countdown') return;
    const next = countdown - dt;
    if (next <= 0) {
      set({ countdown: 0, phase: 'racing' });
    } else {
      set({ countdown: next });
    }
  },

  tickRaceTime: (dt) => {
    const { phase } = get();
    if (phase !== 'racing') return;
    set((s) => ({ raceTime: s.raceTime + dt }));
  },

  checkGate: (carPos) => {
    const { phase, nextGate } = get();
    if (phase !== 'racing') return;
    const gate = GATES[nextGate];
    if (!gate) return;
    if (carPos.distanceTo(gate.position) < gate.radius) {
      const newNext = nextGate + 1;
      if (newNext >= GATES.length) {
        set({ nextGate: newNext, phase: 'finished' });
      } else {
        set({ nextGate: newNext });
      }
    }
  },

  reset: () =>
    set({ phase: 'countdown', countdown: 3.0, raceTime: 0, nextGate: 0 }),
}));

// Keyboard + gamepad input hook. Returns a getInput() function that reads the
// current key-set and gamepad state — call it inside useFrame, not in render.
import { useEffect, useRef } from 'react';

export function useInput() {
  const keys = useRef(new Set());

  useEffect(() => {
    const down = (e) => keys.current.add(e.code);
    const up = (e) => keys.current.delete(e.code);
    window.addEventListener('keydown', down);
    window.addEventListener('keyup', up);
    return () => {
      window.removeEventListener('keydown', down);
      window.removeEventListener('keyup', up);
    };
  }, []);

  const getInput = () => {
    const k = keys.current;
    let throttle = 0;
    let steer = 0;
    let boost = false;
    let drift = false;
    let jump = false;
    let reverse = false;
    let resetPressed = false;

    if (k.has('KeyW') || k.has('ArrowUp')) throttle = 1;
    if (k.has('KeyS') || k.has('ArrowDown')) { throttle = -1; reverse = true; }
    if (k.has('KeyA') || k.has('ArrowLeft')) steer -= 1;
    if (k.has('KeyD') || k.has('ArrowRight')) steer += 1;
    boost = k.has('ShiftLeft');
    drift = k.has('Space');
    jump = k.has('ControlLeft');
    resetPressed = k.has('KeyR');

    // Gamepad — additive with keyboard
    const gp = navigator.getGamepads ? navigator.getGamepads()[0] : null;
    if (gp) {
      let gpSteer = gp.axes[0] ?? 0;
      if (Math.abs(gpSteer) < 0.12) gpSteer = 0;
      steer += gpSteer;

      const rt = gp.buttons[7]?.value ?? 0;
      const lt = gp.buttons[6]?.value ?? 0;
      if (rt > 0.05) throttle = rt;
      if (lt > 0.05) { throttle = -lt; reverse = true; }

      if (gp.buttons[0]?.pressed) jump = true;
      if (gp.buttons[1]?.pressed) resetPressed = true;
      if (gp.buttons[2]?.pressed) boost = true;
      if (gp.buttons[5]?.pressed) drift = true;
    }

    steer = Math.max(-1, Math.min(1, steer));
    return { throttle, steer, boost, drift, jump, reverse, reset: resetPressed };
  };

  return getInput;
}

import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import App from './App.jsx';

createRoot(document.getElementById('root')).render(
  <StrictMode>
    <App />
  </StrictMode>
);

import { Suspense } from 'react';
import { Canvas } from '@react-three/fiber';
import { Environment } from '@react-three/drei';
import { Physics } from '@react-three/rapier';
import * as THREE from 'three';
import Arena from './components/Arena.jsx';
import World from './components/World.jsx';
import Car from './components/Car.jsx';
import ChaseCamera from './components/ChaseCamera.jsx';
import Hud3D from './components/Hud3D.jsx';
import Effects from './components/Effects.jsx';

export default function App() {
  return (
    <Canvas
      gl={{
        antialias: true,
        toneMapping: THREE.ACESFilmicToneMapping,
        toneMappingExposure: 1.0,
        outputColorSpace: THREE.SRGBColorSpace,
      }}
      camera={{ fov: 78, near: 0.1, far: 3000 }}
      style={{ background: '#05060a' }}
    >
      {/* Ink-void background + FogExp2 matching the vanilla canon */}
      <color attach="background" args={['#05060a']} />
      <fogExp2 attach="fog" args={['#05060a', 0.0016]} />

      <Suspense fallback={null}>
        {/* Studio HDR provides reflections only — bg stays ink black */}
        <Environment files="/studio.hdr" background={false} />

        <Physics gravity={[0, -42, 0]} timeStep="vary">
          <Arena />
          <Car />
        </Physics>

        {/* World env elements outside physics — decorative only */}
        <World />
        <ChaseCamera />
        <Hud3D />
        <Effects />
      </Suspense>
    </Canvas>
  );
}

// Arena — track ribbon, rails, gates, boost pads, physics collider, lighting.
// Physics: fixed trimesh RigidBody so Car.jsx raycasts hit the ribbon surface.
import { useMemo, useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import { RigidBody } from '@react-three/rapier';
import * as THREE from 'three';
import { curve, TRACK_WIDTH, GATE_T_VALUES, BOOST_PAD_T_VALUES } from '../trackData.js';
import { boostPadVertex, boostPadFragment } from '../shaders/boostPad.js';
import { trackEnergyVertex, trackEnergyFragment } from '../shaders/trackEnergy.js';

const PALETTE = {
  blue: 0x00a2ff,
  pink: 0xff1f6e,
  lime: 0x57ff6b,
};

// ── Geometry builders ────────────────────────────────────────────────────────

function buildRibbonGeometry() {
  const segments = 420;
  const positions = [];
  const uvs = [];
  const indices = [];
  const up = new THREE.Vector3(0, 1, 0);

  for (let i = 0; i <= segments; i++) {
    const t = i / segments;
    const point = curve.getPointAt(t);
    const tangent = curve.getTangentAt(t);
    const side = new THREE.Vector3().crossVectors(up, tangent).normalize();
    const half = side.clone().multiplyScalar(TRACK_WIDTH / 2);
    positions.push(point.x - half.x, point.y, point.z - half.z);
    positions.push(point.x + half.x, point.y, point.z + half.z);
    uvs.push(0, t * 40, 1, t * 40);
    if (i < segments) {
      const a = i * 2;
      indices.push(a, a + 1, a + 2, a + 1, a + 3, a + 2);
    }
  }

  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geo.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
  geo.setIndex(indices);
  geo.computeVertexNormals();
  return geo;
}

function buildRailGeometry(offset) {
  const samples = 360;
  const up = new THREE.Vector3(0, 1, 0);
  const points = [];
  for (let i = 0; i <= samples; i++) {
    const t = i / samples;
    const point = curve.getPointAt(t);
    const tangent = curve.getTangentAt(t);
    const side = new THREE.Vector3().crossVectors(up, tangent).normalize();
    points.push(
      point.clone().addScaledVector(side, offset).add(new THREE.Vector3(0, 0.9, 0))
    );
  }
  const railCurve = new THREE.CatmullRomCurve3(points, true);
  return new THREE.TubeGeometry(railCurve, 420, 0.18, 8, true);
}

// ── Sub-components ────────────────────────────────────────────────────────────

function TrackRibbon({ ribbonGeo }) {
  const energyRef = useRef();

  const ribbonMat = useMemo(
    () =>
      new THREE.MeshPhysicalMaterial({
        color: 0x0b0e16,
        metalness: 0.85,
        roughness: 0.22,
        clearcoat: 1.0,
        clearcoatRoughness: 0.15,
        side: THREE.DoubleSide,
      }),
    []
  );

  const energyMat = useMemo(
    () =>
      new THREE.ShaderMaterial({
        vertexShader: trackEnergyVertex,
        fragmentShader: trackEnergyFragment,
        uniforms: { uTime: { value: 0 } },
        transparent: true,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
        side: THREE.DoubleSide,
      }),
    []
  );

  useFrame((_, dt) => {
    if (energyRef.current) energyRef.current.uniforms.uTime.value += dt;
  });

  return (
    <>
      {/* Fixed physics trimesh — the ribbon is the collision surface */}
      <RigidBody type="fixed" colliders="trimesh">
        <mesh geometry={ribbonGeo} material={ribbonMat} />
      </RigidBody>
      {/* Non-physics energy overlay — additive, slight y-offset */}
      <mesh
        geometry={ribbonGeo}
        material={energyMat}
        ref={(m) => { if (m) energyRef.current = m.material; }}
        position-y={0.06}
      />
    </>
  );
}

function Rails() {
  const [leftGeo, rightGeo] = useMemo(
    () => [
      buildRailGeometry(-(TRACK_WIDTH / 2 + 1.2)),
      buildRailGeometry(TRACK_WIDTH / 2 + 1.2),
    ],
    []
  );

  const leftMat = useMemo(
    () =>
      new THREE.MeshStandardMaterial({
        color: 0x000000,
        emissive: new THREE.Color(PALETTE.blue),
        emissiveIntensity: 1.6,
      }),
    []
  );
  const rightMat = useMemo(
    () =>
      new THREE.MeshStandardMaterial({
        color: 0x000000,
        emissive: new THREE.Color(PALETTE.pink),
        emissiveIntensity: 1.6,
      }),
    []
  );

  return (
    <>
      <mesh geometry={leftGeo} material={leftMat} />
      <mesh geometry={rightGeo} material={rightMat} />
    </>
  );
}

function Gate({ t, index }) {
  const isFinish = index === GATE_T_VALUES.length - 1;
  const color = isFinish ? PALETTE.lime : index % 2 === 0 ? PALETTE.blue : PALETTE.pink;
  const up = new THREE.Vector3(0, 1, 0);
  const point = curve.getPointAt(t);
  const tangent = curve.getTangentAt(t);
  const side = new THREE.Vector3().crossVectors(up, tangent).normalize();
  const beamAngle = Math.atan2(tangent.x, tangent.z) + Math.PI / 2;

  const mat = useMemo(
    () =>
      new THREE.MeshStandardMaterial({
        color: 0x000000,
        emissive: new THREE.Color(color),
        emissiveIntensity: 1.5,
      }),
    [color]
  );
  const beamMat = useMemo(
    () =>
      new THREE.MeshStandardMaterial({
        color: 0x000000,
        emissive: new THREE.Color(color),
        emissiveIntensity: 1.8,
      }),
    [color]
  );

  const leftPos = point.clone().addScaledVector(side, -(TRACK_WIDTH / 2 + 2.4));
  const rightPos = point.clone().addScaledVector(side, TRACK_WIDTH / 2 + 2.4);

  return (
    <group>
      <mesh
        geometry={new THREE.CylinderGeometry(0.5, 0.5, 22, 12)}
        material={mat}
        position={[leftPos.x, leftPos.y + 11, leftPos.z]}
      />
      <mesh
        geometry={new THREE.CylinderGeometry(0.5, 0.5, 22, 12)}
        material={mat}
        position={[rightPos.x, rightPos.y + 11, rightPos.z]}
      />
      <mesh
        geometry={new THREE.BoxGeometry(TRACK_WIDTH + 6, 0.6, 0.6)}
        material={beamMat}
        position={[point.x, point.y + 22, point.z]}
        rotation-y={beamAngle}
      />
    </group>
  );
}

function BoostPad({ t }) {
  const matRef = useRef();
  const point = curve.getPointAt(t);
  const tangent = curve.getTangentAt(t);
  const angle = Math.atan2(tangent.x, tangent.z);

  const mat = useMemo(
    () =>
      new THREE.ShaderMaterial({
        vertexShader: boostPadVertex,
        fragmentShader: boostPadFragment,
        uniforms: {
          uTime: { value: 0 },
          uColorA: { value: new THREE.Color(PALETTE.blue) },
          uColorB: { value: new THREE.Color(PALETTE.pink) },
        },
        transparent: true,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
      }),
    []
  );

  useFrame((_, dt) => {
    if (matRef.current) matRef.current.uniforms.uTime.value += dt;
  });

  return (
    <mesh
      geometry={new THREE.PlaneGeometry(10, 22)}
      material={mat}
      ref={(m) => { if (m) matRef.current = m.material; }}
      position={[point.x, point.y + 0.25, point.z]}
      rotation-x={-Math.PI / 2}
      rotation-z={-angle}
    />
  );
}

// ── Lighting ─────────────────────────────────────────────────────────────────

function Lighting() {
  return (
    <>
      <ambientLight color={0x1a2030} intensity={0.35} />
      <directionalLight color={0x8fb8ff} intensity={0.85} position={[-180, 320, -140]} />
      {/* Restrained accent pools — geometry carries the color, lights tint surfaces */}
      <pointLight color={PALETTE.blue} intensity={1200} distance={260} decay={2} position={[120, 90, 60]} />
      <pointLight color={PALETTE.pink} intensity={1200} distance={260} decay={2} position={[240, 110, 260]} />
      <pointLight color={PALETTE.lime} intensity={1200} distance={260} decay={2} position={[-80, 80, 240]} />
    </>
  );
}

// ── Main export ───────────────────────────────────────────────────────────────

export default function Arena() {
  const ribbonGeo = useMemo(() => buildRibbonGeometry(), []);

  return (
    <group>
      <TrackRibbon ribbonGeo={ribbonGeo} />
      <Rails />
      {GATE_T_VALUES.map((t, i) => (
        <Gate key={i} t={t} index={i} />
      ))}
      {BOOST_PAD_T_VALUES.map((t, i) => (
        <BoostPad key={i} t={t} />
      ))}
      <Lighting />
    </group>
  );
}

