// ── Neon Ring Toruses ─────────────────────────────────────────────────────────
// 8 giant rings the track threads through — #1 Pinterest board motif.

const RING_CONFIGS = [
  { t: 0.08, radius: 36, tube: 1.5, color: 0x00a2ff, speed: 0.18, yOff: 0 },
  { t: 0.18, radius: 42, tube: 1.8, color: 0xff1f6e, speed: -0.12, yOff: 2 },
  { t: 0.30, radius: 38, tube: 1.4, color: 0x7b4fff, speed: 0.22, yOff: -1 },
  { t: 0.43, radius: 44, tube: 1.6, color: 0x00a2ff, speed: -0.15, yOff: 3 },
  { t: 0.58, radius: 40, tube: 1.5, color: 0xff1f6e, speed: 0.20, yOff: 0 },
  { t: 0.68, radius: 36, tube: 1.3, color: 0x00eeff, speed: -0.25, yOff: 2 },
  { t: 0.78, radius: 45, tube: 2.0, color: 0xff1f6e, speed: 0.14, yOff: -2 },
  { t: 0.90, radius: 38, tube: 1.4, color: 0x7b4fff, speed: -0.18, yOff: 0 },
];

function NeonRings() {
  const ringRefs = useRef([]);

  const rings = useMemo(() => {
    return RING_CONFIGS.map((cfg, i) => {
      const point = curve.getPointAt(cfg.t);
      const tangent = curve.getTangentAt(cfg.t).normalize();

      // Quaternion to align torus Y-axis (its hole axis) with track tangent
      const up = new THREE.Vector3(0, 1, 0);
      const cross = new THREE.Vector3().crossVectors(up, tangent);
      let q;
      if (cross.length() < 0.001) {
        q = new THREE.Quaternion();
      } else {
        q = new THREE.Quaternion().setFromUnitVectors(up, tangent);
      }

      const emissiveColor = new THREE.Color(cfg.color);
      const mat = new THREE.MeshPhysicalMaterial({
        color: 0x000000,
        emissive: emissiveColor,
        emissiveIntensity: 2.2,
        metalness: 1.0,
        roughness: 0.0,
        // Thin-film iridescence gives the soap-bubble gloss the art bible demands
        iridescence: 0.8,
        iridescenceIOR: 2.0,
        iridescenceThicknessRange: [150, 500],
        side: THREE.FrontSide,
      });

      return {
        position: [point.x, point.y + cfg.yOff, point.z],
        quaternion: q,
        geo: new THREE.TorusGeometry(cfg.radius, cfg.tube, 16, 120),
        mat,
        speed: cfg.speed,
        index: i,
      };
    });
  }, []);

  useFrame((_, dt) => {
    ringRefs.current.forEach((mesh, i) => {
      if (!mesh) return;
      // Slow spin around the axis the torus was oriented to
      mesh.rotateOnAxis(new THREE.Vector3(0, 1, 0), rings[i].speed * dt);
    });
  });

  return (
    <>
      {rings.map((r, i) => (
        <mesh
          key={i}
          ref={(m) => { ringRefs.current[i] = m; }}
          geometry={r.geo}
          material={r.mat}
          position={r.position}
          quaternion={[r.quaternion.x, r.quaternion.y, r.quaternion.z, r.quaternion.w]}
        />
      ))}
    </>
  );
}

