// ── Starfield ─────────────────────────────────────────────────────────────────
// Subtle instanced point-dust — far shell, slight drift in useFrame.

function Starfield() {
  const pointsRef = useRef();

  const [geo, mat] = useMemo(() => {
    const count = 3200;
    const pos = new Float32Array(count * 3);
    const trackCenter = new THREE.Vector3(90, 20, 160);
    for (let i = 0; i < count; i++) {
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.acos(2 * Math.random() - 1);
      const r = 550 + Math.random() * 650;
      pos[i * 3] = trackCenter.x + r * Math.sin(phi) * Math.cos(theta);
      pos[i * 3 + 1] = trackCenter.y + r * Math.sin(phi) * Math.sin(theta) - 80;
      pos[i * 3 + 2] = trackCenter.z + r * Math.cos(phi);
    }
    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
    const material = new THREE.PointsMaterial({
      color: 0xaaccff,
      size: 1.8,
      sizeAttenuation: true,
      transparent: true,
      opacity: 0.55,
