// ── Physics constants (tune without touching logic) ───────────────────────────
const GRAVITY = -42;
const HOVER_HEIGHT = 1.35;
const SPRING_STRENGTH = 68;
const SPRING_DAMPING = 11;
const ENGINE_FORCE = 62;
