// ── Main Car component ────────────────────────────────────────────────────────

export default function Car() {
  const carRef = useRef();
  const engineMatRef = useRef();
  const boostLightRef = useRef();

  // Manual physics state (no React state — avoids re-renders per frame)
  const velRef = useRef(new THREE.Vector3());
  const headingRef = useRef(0);
  const pitchRef = useRef(0);
  const rollRef = useRef(0);
  const boostRef = useRef(100);
  const jumpLatchRef = useRef(false);
  const resetLatchRef = useRef(false);
  const padCooldownsRef = useRef(BOOST_PAD_POSITIONS.map(() => 0));

  // Rapier world access
  const { rapier, world } = useRapier();

  // Input
  const getInput = useInput();

  // Race store
  const { phase, tickCountdown, tickRaceTime, checkGate, reset: resetRace } = useRaceStore();
  const phaseRef = useRef(phase);
  useRaceStore.subscribe((s) => { phaseRef.current = s.phase; });

  // Spawn
  const spawn = useMemo(() => getSpawn(), []);

  // Initialise position and heading on mount (after Rapier body is ready)
  const initialised = useRef(false);

  useFrame((_, rawDt) => {
    if (!carRef.current) return;
    const dt = Math.min(rawDt, 1 / 30);

    // ── Initialise at spawn on first frame ───────────────────────────────────
    if (!initialised.current) {
      initialised.current = true;
      headingRef.current = spawn.heading;
      carRef.current.setNextKinematicTranslation({
        x: spawn.position.x,
        y: spawn.position.y,
        z: spawn.position.z,
      });
    }

    const inp = getInput();
    const currentPhase = phaseRef.current;

    // ── Countdown tick ───────────────────────────────────────────────────────
    tickCountdown(dt);
    if (currentPhase === 'racing') tickRaceTime(dt);

    // ── Reset ────────────────────────────────────────────────────────────────
    if (inp.reset && !resetLatchRef.current) {
      resetLatchRef.current = true;
      velRef.current.set(0, 0, 0);
      headingRef.current = spawn.heading;
      pitchRef.current = 0;
      rollRef.current = 0;
      boostRef.current = 100;
      if (currentPhase === 'finished') resetRace();
      carRef.current.setNextKinematicTranslation({
        x: spawn.position.x,
        y: spawn.position.y,
        z: spawn.position.z,
      });
    }
    if (!inp.reset) resetLatchRef.current = false;

    // ── Hover raycast ────────────────────────────────────────────────────────
    const pos = carRef.current.translation();

    const rayOrigin = new rapier.Vector3(pos.x, pos.y + RAY_ORIGIN_OFFSET, pos.z);
    const rayDir = new rapier.Vector3(0, -1, 0);
    const ray = new rapier.Ray(rayOrigin, rayDir);
    const hit = world.castRay(ray, RAY_MAX_TOI, true);

    const groundHeight = hit ? (pos.y + RAY_ORIGIN_OFFSET - hit.toi) : null;
    const grounded = groundHeight !== null && (pos.y - groundHeight) < (HOVER_HEIGHT + 1.1);

    const vel = velRef.current;
    const heading = headingRef.current;
    const forward = new THREE.Vector3(Math.sin(heading), 0, Math.cos(heading));
    const right = new THREE.Vector3(forward.z, 0, -forward.x);
    const raceActive = currentPhase === 'racing';

    // ── Ground physics ───────────────────────────────────────────────────────
    if (grounded) {
      // Hover spring (PD controller toward target height)
      const targetY = groundHeight + HOVER_HEIGHT;
      const displacement = targetY - pos.y;
      vel.y += (displacement * SPRING_STRENGTH - vel.y * SPRING_DAMPING) * dt;

      // Throttle — gated by race active
      const throttle = raceActive ? inp.throttle : 0;
      vel.addScaledVector(forward, throttle * ENGINE_FORCE * dt);

      // Boost
      if (inp.boost && boostRef.current > 0 && raceActive) {
        vel.addScaledVector(forward, BOOST_FORCE * dt);
        boostRef.current = Math.max(0, boostRef.current - BOOST_DRAIN * dt);
      } else {
        boostRef.current = Math.min(100, boostRef.current + BOOST_REFILL * dt);
      }

      // Steering — rate scales with speed for arcade snap
      const speed = vel.length();
      const steerRate = STEER_RATE * Math.max(0.25, Math.min(1.35, speed / 32));
      headingRef.current -= inp.steer * steerRate * dt * (inp.reverse ? -1 : 1);

      // Lateral grip / drift
      const lateral = vel.dot(right);
      const grip = inp.drift ? DRIFT_GRIP : LATERAL_GRIP;
      vel.addScaledVector(right, -lateral * grip * dt);
      if (inp.drift) headingRef.current -= inp.steer * DRIFT_YAW * dt;

      // Rolling resistance
      vel.multiplyScalar(1 - ROLLING_RESISTANCE * dt);

      // Jump impulse
      if (inp.jump && !jumpLatchRef.current) {
        vel.y = JUMP_VEL;
        jumpLatchRef.current = true;
      }
    } else {
      // Aerial
      vel.y += GRAVITY * dt;
      headingRef.current -= inp.steer * AERIAL_STEER * dt;
      pitchRef.current = THREE.MathUtils.lerp(pitchRef.current, inp.throttle * -0.35, dt * 3);
    }
    if (!inp.jump) jumpLatchRef.current = false;

    // ── Integrate position ───────────────────────────────────────────────────
    const newPos = {
      x: pos.x + vel.x * dt,
      y: pos.y + vel.y * dt,
      z: pos.z + vel.z * dt,
    };
    carRef.current.setNextKinematicTranslation(newPos);

    // ── Visual lean ──────────────────────────────────────────────────────────
    const speedRatio = Math.min(1, vel.length() / 70);
    rollRef.current = THREE.MathUtils.lerp(
      rollRef.current,
      -inp.steer * (0.22 + speedRatio * 0.3),
      dt * 6
    );
    if (grounded) pitchRef.current = THREE.MathUtils.lerp(pitchRef.current, 0, dt * 5);

    const q = new THREE.Quaternion().setFromEuler(
      new THREE.Euler(pitchRef.current, headingRef.current + Math.PI, rollRef.current, 'YXZ')
    );
    carRef.current.setNextKinematicRotation({ x: q.x, y: q.y, z: q.z, w: q.w });

    // ── Boost pad proximity ──────────────────────────────────────────────────
    const carVec = new THREE.Vector3(newPos.x, newPos.y, newPos.z);
    padCooldownsRef.current = padCooldownsRef.current.map((cd, i) => {
      const next = Math.max(0, cd - dt);
      if (next <= 0 && carVec.distanceTo(BOOST_PAD_POSITIONS[i]) < BOOST_PAD_RADIUS) {
        // Apply boost pad
        vel.addScaledVector(forward, BOOST_PAD_VEL_BONUS);
        boostRef.current = Math.min(100, boostRef.current + BOOST_PAD_CHARGE_BONUS);
        return BOOST_PAD_COOLDOWN;
      }
      return next;
    });

    // ── Gate check ───────────────────────────────────────────────────────────
    checkGate(carVec);

    // ── Boost visuals ────────────────────────────────────────────────────────
    const boosting = inp.boost && boostRef.current > 0 && raceActive;
    if (engineMatRef.current) {
      engineMatRef.current.emissiveIntensity = THREE.MathUtils.lerp(
        engineMatRef.current.emissiveIntensity,
        boosting ? 5.0 : 1.5,
        dt * 8
      );
    }
    if (boostLightRef.current) {
      boostLightRef.current.intensity = THREE.MathUtils.lerp(
        boostLightRef.current.intensity,
        boosting ? 140 : 25,
        dt * 8
      );
    }

    // ── Write to shared carPhysics for ChaseCamera + HUD ────────────────────
    carPhysics.position.set(newPos.x, newPos.y, newPos.z);
    carPhysics.heading = headingRef.current;
    carPhysics.velocity.copy(vel);
    carPhysics.boost = boostRef.current;
    carPhysics.isBoosting = boosting;
  });

  return (
    <RigidBody
      ref={carRef}
      type="kinematicPosition"
      colliders={false}
    >
      <CarMesh engineMatRef={engineMatRef} boostLightRef={boostLightRef} />
    </RigidBody>
  );
}

// ChaseCamera — exponential-smoothed chase camera, FOV widens while boosting.
// Reads carPhysics module-level state (no React re-renders per frame).
import { useRef } from 'react';
import { useFrame, useThree } from '@react-three/fiber';
import * as THREE from 'three';
import { carPhysics } from '../carState.js';
import { useRaceStore } from '../state.js';

const OFFSET_BACK = -11;
const OFFSET_UP = 4.4;
const LOOK_AHEAD = 7;
const LOOK_UP = 1.2;
const SMOOTH_SPEED = 6;
const FOV_NORMAL = 78;
const FOV_BOOST = 88;
const FOV_SMOOTH = 4;

export default function ChaseCamera() {
  const { camera } = useThree();
  const camPos = useRef(new THREE.Vector3());
  const camLook = useRef(new THREE.Vector3());
  const fovRef = useRef(FOV_NORMAL);
  const seeded = useRef(false);

  useFrame((_, dt) => {
    const { position, heading, isBoosting } = carPhysics;
    const phase = useRaceStore.getState().phase;

    const fwd = new THREE.Vector3(Math.sin(heading), 0, Math.cos(heading));

    const targetPos = position
      .clone()
      .addScaledVector(fwd, OFFSET_BACK)
      .add(new THREE.Vector3(0, OFFSET_UP, 0));
    const targetLook = position
      .clone()
      .addScaledVector(fwd, LOOK_AHEAD)
      .add(new THREE.Vector3(0, LOOK_UP, 0));

    // Seed camera on first frame to avoid initial snap
    if (!seeded.current) {
      seeded.current = true;
      camPos.current.copy(targetPos);
      camLook.current.copy(targetLook);
      camera.position.copy(targetPos);
    }

    const alpha = 1 - Math.exp(-SMOOTH_SPEED * dt);
    camPos.current.lerp(targetPos, alpha);
    camLook.current.lerp(targetLook, alpha);

    camera.position.copy(camPos.current);
    camera.lookAt(camLook.current);

    // FOV widen during boost
    const boosting = isBoosting && phase === 'racing';
    fovRef.current = THREE.MathUtils.lerp(
      fovRef.current,
      boosting ? FOV_BOOST : FOV_NORMAL,
      1 - Math.exp(-FOV_SMOOTH * dt)
    );
    camera.fov = fovRef.current;
    camera.updateProjectionMatrix();
  });

  return null;
}
